.lay{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:40px;align-items:start;padding-top:38px;padding-bottom:60px}
main{counter-reset:sec}.sec{scroll-margin-top:16px;counter-increment:sec}.sec+.sec{margin-top:46px}
.sec>h2{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 12px;margin:0 0 16px;padding-bottom:10px;border-bottom:1px solid var(--line);font-size:20px;color:#fff}
.sec>h2::before{content:counter(sec,decimal-leading-zero);font:800 13px var(--mono);letter-spacing:.06em;color:var(--org)}.sec>h2 small{font-size:13px;font-weight:400;color:var(--mut)}
.pane{background:var(--panel);border:1px solid var(--line2)}
ol.kpl{margin:0;padding:0;list-style:none;counter-reset:k}ol.kpl li{position:relative;padding:14px 20px 14px 62px;counter-increment:k;font-size:15px;line-height:1.8;color:var(--ink)}ol.kpl li+li{border-top:1px solid var(--line2)}
ol.kpl li::before{content:counter(k,decimal-leading-zero);position:absolute;left:20px;top:14px;font:800 14px/1.8 var(--mono);color:var(--gcl)}
.feats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.feat{display:flex;flex-direction:column;padding:16px 18px;background:var(--panel);border:1px solid var(--line2);border-top:2px solid var(--gc)}
.feat .lv{font:800 11.5px var(--mono);letter-spacing:.12em;color:var(--gcl)}.feat h3{margin:8px 0 6px;font-size:16.5px;color:#fff}.feat p{margin:0 0 14px;font-size:14px;line-height:1.75;color:var(--txt)}
.feat .eff{margin:auto 0 0;padding-top:12px;border-top:1px dashed var(--line);font-size:12.5px;color:var(--mut)}.feat .eff b{color:var(--orgl);font-weight:600}.feat .run{margin:6px 0 0;font-size:12.5px;color:var(--mut)}.feat .run b{color:#cfd6e0;font-weight:600}
.callout{padding:14px 18px;background:rgba(95,179,255,.06);border:1px solid rgba(95,179,255,.25);border-left:2px solid var(--blue)}.callout+.callout{margin-top:10px}.callout h3{margin:0 0 4px;font-size:15px;color:#9fd0ff}.callout p{margin:0;line-height:1.8;color:var(--ink)}
.score{display:inline-flex;align-items:center;gap:8px;margin:0 0 12px;padding:5px 12px;border:1px solid var(--line);font:600 12.5px var(--mono);color:var(--mut)}.score b{color:var(--orgl)}
.qz{padding:18px 20px;background:var(--panel);border:1px solid var(--line2)}.qz+.qz{margin-top:12px}
.qq{display:flex;gap:10px;font-size:15.5px;font-weight:700;line-height:1.7;color:#fff}.qq .no{flex:none;font-family:var(--mono);color:var(--org)}.qq small{flex:none;align-self:flex-start;margin-top:3px;padding:0 7px;border:1px solid rgba(95,179,255,.4);color:#9fd0ff;font:600 11px/18px var(--mono);white-space:nowrap}
.ops{display:grid;gap:8px;margin:14px 0 0}.op{display:flex;gap:12px;align-items:flex-start;width:100%;padding:10px 14px;border:1px solid var(--line);background:rgba(255,255,255,.02);color:var(--txt);font:inherit;font-size:14.5px;line-height:1.6;text-align:left;cursor:pointer;transition:border-color .15s,background-color .15s}
.op:hover:not(:disabled){border-color:rgba(255,255,255,.4);background:rgba(255,255,255,.05)}.op .l{flex:none;width:24px;height:24px;border:1px solid var(--line);font:700 12px/22px var(--mono);text-align:center;color:var(--mut)}
.op:disabled{cursor:default}.op.ok{border-color:var(--ok);background:rgba(91,227,140,.08)}.op.ok .l{border-color:var(--ok);background:var(--ok);color:#0b111c}.op.bad{border-color:var(--bad);background:rgba(255,107,107,.08)}.op.bad .l{border-color:var(--bad);background:var(--bad);color:#0b111c}
.qa{display:flex;align-items:center;gap:14px;margin-top:12px}.reveal{padding:0;border:0;background:none;color:var(--blue);font:inherit;font-size:13.5px;font-weight:600;cursor:pointer}.reveal:hover{text-decoration:underline}
.verdict{font:700 13px var(--mono)}.verdict.ok{color:var(--ok)}.verdict.bad{color:var(--bad)}
.ex{margin-top:12px;padding:12px 16px;background:rgba(91,227,140,.06);border-left:2px solid var(--ok);font-size:14px;line-height:1.8;color:var(--txt)}.ex b{margin-right:6px;color:var(--ok)}.ex a{white-space:nowrap}
.archs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.ac{display:flex;flex-direction:column;gap:8px;padding:16px 18px;background:var(--panel);border:1px solid var(--line2);transition:border-color .15s,background-color .15s}.ac:hover{border-color:rgba(255,255,255,.3);background:var(--panel2)}
.ac h3{display:flex;align-items:center;gap:8px;margin:0;font-size:15.5px;color:#fff}.kind{padding:0 7px;border:1px solid var(--line);font:700 11px/20px var(--mono);color:var(--mut)}.kind.must{border-color:rgba(255,153,0,.6);color:var(--orgl)}.kind.opt{border-style:dashed}
.ac p{margin:0;font-size:14px;line-height:1.7;color:var(--txt)}.btns{display:flex;flex-wrap:wrap;gap:8px;margin-top:auto;padding-top:6px}
.lbtn{display:inline-flex;align-items:center;gap:6px;height:34px;padding:0 14px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--ink);font-size:13px;font-weight:700;text-decoration:none;white-space:nowrap;transition:border-color .15s,background-color .15s}.lbtn:hover{border-color:rgba(255,255,255,.45)}
.lbtn.pri{background:var(--org);border-color:var(--org);color:#16191f}.lbtn.pri:hover{background:#ffad33;border-color:#ffad33}
dl.facts{margin:0;padding:2px 20px}dl.facts>div{display:grid;grid-template-columns:110px 1fr;gap:12px;padding:12px 0}dl.facts>div+div{border-top:1px solid var(--line2)}dl.facts dt{font:600 12.5px/1.9 var(--mono);color:var(--mut)}dl.facts dd{margin:0;font-size:14.5px;line-height:1.75;color:var(--ink)}
.pn{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:46px}.pn a{display:flex;flex-direction:column;gap:2px;padding:14px 18px;background:var(--panel);border:1px solid var(--line2);text-decoration:none;color:#fff;transition:border-color .15s}.pn a:hover{border-color:rgba(255,255,255,.3)}.pn a small{font:600 11.5px var(--mono);letter-spacing:.1em;color:var(--mut)}.pn a b{display:inline-flex;align-items:center;gap:6px;font-size:15px}.pn a.nx{text-align:right;align-items:flex-end}
.side{position:sticky;top:20px;display:grid;gap:12px}.toc{padding:12px 0;background:var(--panel);border:1px solid var(--line2)}.toc b{display:block;padding:0 18px 8px;font:700 11px var(--mono);letter-spacing:.14em;color:var(--mut)}
.toc a{display:block;padding:6px 18px 6px 15px;border-left:2px solid transparent;color:var(--txt);font-size:14px;text-decoration:none}.toc a:hover{color:#fff;background:rgba(255,255,255,.03)}.toc a.on{border-left-color:var(--org);color:#fff;font-weight:700}
.quick{padding:14px 18px;background:var(--panel);border:1px solid var(--line2);font-size:13.5px}.quick b{display:block;margin-bottom:8px;font:700 11px var(--mono);letter-spacing:.14em;color:var(--mut)}.quick ul{margin:0;padding:0;list-style:none}.quick li{display:flex;justify-content:space-between;gap:10px;padding:4px 0}.quick li span{color:var(--mut)}.quick li em{font-style:normal;font-weight:700;font-family:var(--mono);color:var(--orgl);text-align:right}
@media (max-width:1060px){.lay{grid-template-columns:1fr}.side{display:none}.feats{grid-template-columns:1fr}}
@media (max-width:760px){.wrap{padding:0 16px}.hero .wrap{padding-top:28px}.hero h1{font-size:32px}.stats{grid-template-columns:1fr 1fr}.stats li:nth-child(3){border-left:0}.stats li:nth-child(n+3){border-top:1px solid var(--line)}.stats b{font-size:22px}.search{flex:1 1 100%}.top .brand{display:none}
  .tiles,.archs,.pn{grid-template-columns:1fr}.svh-in{gap:18px;margin-top:16px}.svh-ic{width:56px;height:56px;outline-offset:5px}.svh h1{font-size:30px}.lead{font-size:16px}.lay{padding-top:28px}ol.kpl li{padding:12px 16px 12px 52px}ol.kpl li::before{left:16px;top:12px}dl.facts{padding:2px 16px}dl.facts>div{grid-template-columns:1fr;gap:0}.pn a.nx{text-align:left;align-items:flex-start}}
